using System;
using System.Collections.Generic;

class Program
{
    static int CountPositive(List<int> values)
    {
        int count = 0;
        foreach (int value in values)
        {
            if (value > 0)
            {
                count += 1;
            }
        }
        return count;
    }

    static void Main()
    {
        Console.WriteLine(CountPositive(new List<int> { 3, -1, 2 }));
    }
}
